#!/bin/sh
# Sync this personal fork onto upstream/dev and re-link it as the active
# plugin. Replaces the previous one-line `omc-sync` alias (see
# PERSONAL_SETUP.md).
#
# Why this is a script and not an alias: `git rebase` refuses to run with a
# dirty worktree, and dist/ + bridge/ are tracked but regenerated by every
# `npm run build` — so a plain alias fails immediately whenever you have
# built since the last sync. Discarding those two paths before the rebase is
# safe precisely because this script rebuilds them a few lines later; the
# warning in PERSONAL_SETUP.md is about restoring WITHOUT rebuilding.
#
# Any dirty path outside dist/ and bridge/ is real work, so we stop instead
# of touching it.

set -e

REPO_DIR=$(cd "$(dirname "$0")/../.." && pwd)
cd "$REPO_DIR"

UNEXPECTED=$(git status --porcelain -- . ':(exclude)dist/*' ':(exclude)bridge/*')
if [ -n "$UNEXPECTED" ]; then
  echo "Refusing to sync: uncommitted changes outside dist/ and bridge/:" >&2
  echo "$UNEXPECTED" >&2
  echo >&2
  echo "Commit or stash them first, then re-run this script." >&2
  exit 1
fi

# A fresh clone of the fork only has origin. Fail with the fix rather than
# git's "'upstream' does not appear to be a git repository".
if ! git remote get-url upstream >/dev/null 2>&1; then
  echo "No 'upstream' remote in this checkout." >&2
  echo "Run scripts/personal/apply-local-setup.sh once — it adds it." >&2
  exit 1
fi

# Fetch BEFORE discarding build output: fetching does not touch the worktree,
# so a network failure here leaves dist/ and bridge/ exactly as they were.
# Discarding first meant a failed fetch left the running HUD reading reverted
# output with no rebuild coming (the hazard PERSONAL_SETUP.md warns about).
echo "Fetching upstream/dev"
git fetch upstream dev

if ! git diff --quiet -- dist bridge || ! git diff --cached --quiet -- dist bridge; then
  echo "Discarding stale build output in dist/ and bridge/ (rebuilt below)"
  git restore --source=HEAD --staged --worktree -- dist bridge
fi

if ! git rebase upstream/dev; then
  echo >&2
  echo "Rebase stopped on a conflict. Resolve the files listed by 'git status'," >&2
  echo "run 'git rebase --continue', then re-run this script." >&2
  echo "To abandon the sync entirely: git rebase --abort" >&2
  exit 1
fi

npm install
npm run build
# Setup must run through this checkout's OWN bridge/cli.cjs, not whatever
# `omc` resolves to on PATH. omc's installer copies file-based templates
# (e.g. the HUD cache wrapper script) via getPackageDir(), which resolves
# from the __dirname of the CLI binary actually running -- it does NOT
# consult OMC_PLUGIN_ROOT for that. The globally installed `omc` would
# silently re-copy the unpatched marketplace version of that wrapper even
# with OMC_PLUGIN_ROOT set correctly.
OMC_PLUGIN_ROOT="$REPO_DIR" node "$REPO_DIR/bridge/cli.cjs" setup --plugin-dir-mode

# setup re-creates the standalone hook copies on machines whose settings.json
# has no marketplace OMC entry, so prune them again here — otherwise every
# sync would quietly undo what the bootstrap script reconciled.
CONFIG_DIR="${CLAUDE_CONFIG_DIR:-$HOME/.claude}"
node "$REPO_DIR/scripts/personal/prune-standalone-hooks.mjs" \
  "$CONFIG_DIR" "$REPO_DIR" "$CONFIG_DIR/settings.json"

echo
echo "Synced. Start a NEW Claude Code session to pick this up."
